// ============================================================
// EFAS N TEPE - META WHATSAPP WEBHOOK DURUM KONTROL
// ============================================================
// Bu node Meta'dan POST ile gelen webhook bildirimlerini işler.
//
// Yakaladigi durumlar:
// - sent       -> GONDERILDI
// - delivered  -> TESLIM_EDILDI
// - read       -> OKUNDU
// - failed     -> BASARISIZ
// - deleted    -> SILINDI
//
// Ayrica:
// - Gelen WhatsApp mesajlarini yakalar
// - Meta hata kodlarini yakalar
// - Telefon numarasini yakalar
// - Message ID'yi yakalar
// - Pricing / conversation bilgilerini yakalar
// ============================================================

const items = $input.all();

const results = [];

// ------------------------------------------------------------
// YARDIMCI FONKSIYONLAR
// ------------------------------------------------------------

function safeString(value) {
  if (value === null || value === undefined) {
    return null;
  }

  return String(value);
}

function timestampToDate(timestamp) {
  if (!timestamp) {
    return null;
  }

  const number = Number(timestamp);

  if (!Number.isFinite(number)) {
    return null;
  }

  try {
    return new Date(number * 1000).toISOString();
  } catch {
    return null;
  }
}

function getErrorInformation(errors) {
  if (!Array.isArray(errors) || errors.length === 0) {
    return {
      hataVar: false,
      hataKodu: null,
      hataBasligi: null,
      hataMesaji: null,
      hataDetayi: null,
      hatalar: [],
    };
  }

  const codes = [];
  const titles = [];
  const messages = [];
  const details = [];

  for (const error of errors) {

    if (error?.code !== undefined && error?.code !== null) {
      codes.push(String(error.code));
    }

    if (error?.title) {
      titles.push(String(error.title));
    }

    if (error?.message) {
      messages.push(String(error.message));
    }

    if (error?.error_data?.details) {
      details.push(String(error.error_data.details));
    }
  }

  return {
    hataVar: true,

    hataKodu:
      codes.length > 0
        ? codes.join(', ')
        : null,

    hataBasligi:
      titles.length > 0
        ? titles.join(' | ')
        : null,

    hataMesaji:
      messages.length > 0
        ? messages.join(' | ')
        : null,

    hataDetayi:
      details.length > 0
        ? details.join(' | ')
        : null,

    hatalar: errors,
  };
}

function getReadableStatus(status, errorInfo) {

  const state = String(status ?? '')
    .trim()
    .toLowerCase();

  switch (state) {

    case 'sent':
      return {
        durum: 'GONDERILDI',
        aciklama:
          'Meta mesaji WhatsApp sistemine gonderdi.',
        teslimEdildi: false,
        okundu: false,
        basarisiz: false,
      };

    case 'delivered':
      return {
        durum: 'TESLIM_EDILDI',
        aciklama:
          'Mesaj alicinin WhatsApp hesabina teslim edildi.',
        teslimEdildi: true,
        okundu: false,
        basarisiz: false,
      };

    case 'read':
      return {
        durum: 'OKUNDU',
        aciklama:
          'Alici WhatsApp mesajini okudu.',
        teslimEdildi: true,
        okundu: true,
        basarisiz: false,
      };

    case 'failed':

      return {
        durum: 'BASARISIZ',

        aciklama:
          errorInfo.hataDetayi ||
          errorInfo.hataMesaji ||
          errorInfo.hataBasligi ||
          'Meta mesaji teslim edemedi.',

        teslimEdildi: false,
        okundu: false,
        basarisiz: true,
      };

    case 'deleted':
      return {
        durum: 'SILINDI',
        aciklama:
          'Meta mesaj durumunu deleted olarak bildirdi.',
        teslimEdildi: false,
        okundu: false,
        basarisiz: false,
      };

    default:
      return {
        durum:
          state
            ? state.toUpperCase()
            : 'BILINMEYEN_DURUM',

        aciklama:
          'Meta tarafindan farkli bir mesaj durumu bildirildi.',

        teslimEdildi: false,
        okundu: false,
        basarisiz: false,
      };
  }
}

// ------------------------------------------------------------
// ANA ISLEM
// ------------------------------------------------------------

for (const item of items) {

  const incoming = item.json ?? {};

  // n8n Webhook node'u POST body'sini genellikle body altinda verir.
  // Ancak farkli n8n surumleri / testlerde direkt JSON gelebilir.
  const body =
    incoming.body &&
    typeof incoming.body === 'object'
      ? incoming.body
      : incoming;

  const entries =
    Array.isArray(body.entry)
      ? body.entry
      : [];

  // ----------------------------------------------------------
  // ENTRY YOKSA
  // ----------------------------------------------------------

  if (entries.length === 0) {

    results.push({
      json: {
        eventType: 'WEBHOOK',
        durum: 'WEBHOOK_ALINDI',
        aciklama:
          'POST webhook istegi alindi fakat Meta entry verisi bulunamadi.',
        hataVar: false,
        hamVeri: body,
      },
    });

    continue;
  }

  // ----------------------------------------------------------
  // ENTRY
  // ----------------------------------------------------------

  for (const entry of entries) {

    const changes =
      Array.isArray(entry.changes)
        ? entry.changes
        : Array.isArray(entry.change)
          ? entry.change
          : [];

    // --------------------------------------------------------
    // CHANGE YOKSA
    // --------------------------------------------------------

    if (changes.length === 0) {

      results.push({
        json: {
          eventType: 'WEBHOOK',
          durum: 'CHANGE_BULUNAMADI',
          aciklama:
            'Meta entry geldi fakat changes alani bulunamadi.',
          entryId: entry?.id ?? null,
          hataVar: false,
          hamVeri: entry,
        },
      });

      continue;
    }

    // --------------------------------------------------------
    // CHANGES
    // --------------------------------------------------------

    for (const change of changes) {

      const value =
        change?.value &&
        typeof change.value === 'object'
          ? change.value
          : {};

      const metadata =
        value?.metadata ?? {};

      const displayPhoneNumber =
        metadata?.display_phone_number ?? null;

      const phoneNumberId =
        metadata?.phone_number_id ?? null;

      const field =
        change?.field ?? null;

      // ======================================================
      // MESAJ DURUMLARI
      // ======================================================

      const statuses =
        Array.isArray(value.statuses)
          ? value.statuses
          : [];

      for (const statusObject of statuses) {

        const metaStatus =
          safeString(statusObject?.status)?.toLowerCase()
          ?? null;

        const errors =
          Array.isArray(statusObject?.errors)
            ? statusObject.errors
            : [];

        const errorInfo =
          getErrorInformation(errors);

        const readable =
          getReadableStatus(
            metaStatus,
            errorInfo
          );

        const conversation =
          statusObject?.conversation ?? {};

        const pricing =
          statusObject?.pricing ?? {};

        const recipientId =
          statusObject?.recipient_id ?? null;

        const messageId =
          statusObject?.id ?? null;

        const timestamp =
          statusObject?.timestamp ?? null;

        results.push({
          json: {

            // ================================================
            // EVENT
            // ================================================

            eventType:
              'MESSAGE_STATUS',

            // ================================================
            // TELEFON
            // ================================================

            telefon:
              recipientId,

            // ================================================
            // MESAJ
            // ================================================

            messageId:
              messageId,

            // ================================================
            // DURUM
            // ================================================

            durum:
              readable.durum,

            metaDurumu:
              metaStatus,

            aciklama:
              readable.aciklama,

            // ================================================
            // KOLAY FILTRELEME
            // ================================================

            metaKabul:
              metaStatus === 'sent' ||
              metaStatus === 'delivered' ||
              metaStatus === 'read',

            gonderildi:
              metaStatus === 'sent' ||
              metaStatus === 'delivered' ||
              metaStatus === 'read',

            teslimEdildi:
              readable.teslimEdildi,

            okundu:
              readable.okundu,

            basarisiz:
              readable.basarisiz,

            // ================================================
            // HATA
            // ================================================

            hataVar:
              errorInfo.hataVar ||
              metaStatus === 'failed',

            hataKodu:
              errorInfo.hataKodu,

            hataBasligi:
              errorInfo.hataBasligi,

            hataMesaji:
              errorInfo.hataMesaji,

            hataDetayi:
              errorInfo.hataDetayi,

            // ================================================
            // ZAMAN
            // ================================================

            timestamp:
              timestamp,

            tarih:
              timestampToDate(timestamp),

            // ================================================
            // CONVERSATION
            // ================================================

            conversationId:
              conversation?.id ?? null,

            conversationOrigin:
              conversation?.origin?.type ?? null,

            conversationExpiration:
              conversation?.expiration_timestamp ?? null,

            // ================================================
            // PRICING
            // ================================================

            pricingModel:
              pricing?.pricing_model ?? null,

            pricingCategory:
              pricing?.category ?? null,

            billable:
              pricing?.billable ?? null,

            // ================================================
            // WHATSAPP BUSINESS
            // ================================================

            displayPhoneNumber:
              displayPhoneNumber,

            phoneNumberId:
              phoneNumberId,

            field:
              field,

            // ================================================
            // DEBUG
            // ================================================

            metaErrors:
              errorInfo.hatalar,
          },
        });
      }

      // ======================================================
      // GELEN WHATSAPP MESAJLARI
      // ======================================================

      const messages =
        Array.isArray(value.messages)
          ? value.messages
          : [];

      const incomingProfileName =
        Array.isArray(value.contacts) && value.contacts.length > 0
          ? (value.contacts[0]?.profile?.name ?? null)
          : null;

      for (const message of messages) {

        const messageType =
          message?.type ?? null;

        let messageText = null;

        // TEXT
        if (messageType === 'text') {
          messageText =
            message?.text?.body ?? null;
        }

        // BUTTON
        else if (messageType === 'button') {
          messageText =
            message?.button?.text ?? null;
        }

        // INTERACTIVE BUTTON
        else if (
          messageType === 'interactive' &&
          message?.interactive?.type === 'button_reply'
        ) {
          messageText =
            message?.interactive?.button_reply?.title
            ?? null;
        }

        // INTERACTIVE LIST
        else if (
          messageType === 'interactive' &&
          message?.interactive?.type === 'list_reply'
        ) {
          messageText =
            message?.interactive?.list_reply?.title
            ?? null;
        }

        const timestamp =
          message?.timestamp ?? null;

        results.push({
          json: {

            eventType:
              'INCOMING_MESSAGE',

            telefon:
              message?.from ?? null,

            profilAdi:
              incomingProfileName,

            messageId:
              message?.id ?? null,

            durum:
              'GELEN_MESAJ',

            metaDurumu:
              'incoming',

            aciklama:
              'WhatsApp kullanicisindan mesaj alindi.',

            mesajTipi:
              messageType,

            mesajMetni:
              messageText,

            timestamp:
              timestamp,

            tarih:
              timestampToDate(timestamp),

            displayPhoneNumber:
              displayPhoneNumber,

            phoneNumberId:
              phoneNumberId,

            field:
              field,

            hataVar:
              false,

            hamMesaj:
              message,
          },
        });
      }

      // ======================================================
      // CONTACTS VARSA
      // ======================================================

      const contacts =
        Array.isArray(value.contacts)
          ? value.contacts
          : [];

      // Message yok ama contact geldiyse bilgi kaybolmasin
      if (
        contacts.length > 0 &&
        messages.length === 0 &&
        statuses.length === 0
      ) {

        for (const contact of contacts) {

          results.push({
            json: {

              eventType:
                'CONTACT',

              durum:
                'CONTACT_ALINDI',

              telefon:
                contact?.wa_id ?? null,

              profilAdi:
                contact?.profile?.name ?? null,

              displayPhoneNumber:
                displayPhoneNumber,

              phoneNumberId:
                phoneNumberId,

              field:
                field,

              hataVar:
                false,
            },
          });
        }
      }

      // ======================================================
      // STATUS VE MESSAGE YOKSA
      // ======================================================

      if (
        statuses.length === 0 &&
        messages.length === 0 &&
        contacts.length === 0
      ) {

        results.push({
          json: {

            eventType:
              'OTHER',

            durum:
              'DIGER_WEBHOOK_EVENT',

            aciklama:
              'Webhook alindi fakat messages veya statuses bulunamadi.',

            displayPhoneNumber:
              displayPhoneNumber,

            phoneNumberId:
              phoneNumberId,

            field:
              field,

            hataVar:
              false,

            hamVeri:
              value,
          },
        });
      }
    }
  }
}

// ------------------------------------------------------------
// SON GUVENLIK
// ------------------------------------------------------------

if (results.length === 0) {

  return [
    {
      json: {
        eventType:
          'WEBHOOK',

        durum:
          'WEBHOOK_ALINDI',

        aciklama:
          'Webhook calisti ancak islenecek veri bulunamadi.',

        hataVar:
          false,

        hamVeri:
          items.map(item => item.json),
      },
    },
  ];
}

// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return results;

const items = $input.all();

return [{
  json: {
    durum: 'MESAJ_GONDERILMEDI_ONIZLEME',
    sablon: 'efas_ntepe_gorsel_2',
    dil: 'tr',
    gorsel: 'https://xrex.com.tr/efas-ntepe-gorsel-2.jpg',
    tekilAliciSayisi: items.length,
    mesajlar: items.map(item => ({
      telefon: item.json.phone,
      payload: item.json.payload
    }))
  }
}];

const r = $input.first().json;
const messageId = r.messages?.[0]?.id ?? null;
const status = r.messages?.[0]?.message_status ?? null;

return [{
  json: {
    metaKabul: Boolean(messageId),
    messageId,
    messageStatus: status,
    durum: messageId ? 'META_KABUL_ETTI' : 'META_YANITI_KONTROL_EDIN',
    metaResponse: r
  }
}];

const f = $input.first().json;

const read = (key) => String(f[key] ?? '').trim();

const PHONE_NUMBER_ID = '1342496342275726';
const API_VERSION = 'v25.0';
const TEMPLATE_NAME = 'efas_ntepe_gorsel_2';
const LANGUAGE_CODE = 'tr';
const IMAGE_URL = 'https://xrex.com.tr/efas-ntepe-gorsel-2.jpg';

const mode = read('Islem');
const recipientsRaw = read('Alicilar');
const permission = read('Izin teyidi').toUpperCase();

if (!['ONIZLEME', 'TEK_TEST', 'TOPLU_GONDER'].includes(mode)) {
  throw new Error('Islem seciniz.');
}

if (!recipientsRaw) {
  throw new Error('En az bir telefon numarasi girin.');
}

const lines = recipientsRaw
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

if (!lines.length) {
  throw new Error('En az bir telefon numarasi girin.');
}

if (lines.length > 250) {
  throw new Error('Bir calistirmada en fazla 250 telefon numarasi kullanabilirsiniz.');
}

const seen = new Set();
const result = [];

for (let i = 0; i < lines.length; i++) {

  let rawPhone = lines[i];

  if (rawPhone.includes('|')) {
    rawPhone = rawPhone.split('|')[0].trim();
  }

  if (!/^[+\d\s().-]+$/.test(rawPhone)) {
    throw new Error(`${i + 1}. satir: telefon bicimi gecersiz.`);
  }

  let phone = rawPhone.replace(/\D/g, '');

  if (phone.startsWith('00')) {
    phone = phone.slice(2);
  }

  if (/^05\d{9}$/.test(phone)) {
    phone = '9' + phone;
  }

  if (/^5\d{9}$/.test(phone)) {
    phone = '90' + phone;
  }

  if (!/^[1-9]\d{7,14}$/.test(phone)) {
    throw new Error(`${i + 1}. satir: telefon numarasi gecersiz. Ornek: 905XXXXXXXXX`);
  }

  if (seen.has(phone)) {
    continue;
  }

  seen.add(phone);

  const payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'template',
    template: {
      name: TEMPLATE_NAME,
      language: {
        code: LANGUAGE_CODE
      },
      components: [
        {
          type: 'header',
          parameters: [
            {
              type: 'image',
              image: {
                link: IMAGE_URL
              }
            }
          ]
        }
      ]
    }
  };

  result.push({
    json: {
      mode,
      sira: result.length + 1,
      toplamAlici: 0,
      phone,
      phoneNumberId: PHONE_NUMBER_ID,
      apiVersion: API_VERSION,
      templateName: TEMPLATE_NAME,
      languageCode: LANGUAGE_CODE,
      imageUrl: IMAGE_URL,
      payload
    }
  });
}

if (!result.length) {
  throw new Error('Gecerli alici bulunamadi.');
}

if (mode === 'TEK_TEST' && result.length !== 1) {
  throw new Error('TEK_TEST icin sadece 1 telefon numarasi girin.');
}

if (mode === 'TOPLU_GONDER' && permission !== 'EVET') {
  throw new Error('TOPLU_GONDER icin Izin teyidi alanina EVET yazin.');
}

for (const item of result) {
  item.json.toplamAlici = result.length;
}

return result;

const items = $input.all();
const state = $getWorkflowStaticData('global');

if (!Number.isInteger(state.efasNtepeRoundRobin)) {
  state.efasNtepeRoundRobin = 0;
}

const ekip = [
  { id: 23564, ad: 'Duygu Ayyayla' },
  { id: 23562, ad: 'Burcu Kansu' }
];

return items.map((item) => {
  const j = item.json || {};

  const atanan = ekip[state.efasNtepeRoundRobin % ekip.length];
  state.efasNtepeRoundRobin =
    (state.efasNtepeRoundRobin + 1) % ekip.length;

  let telefon = String(j.telefon || '').replace(/\D/g, '');
  if (telefon.startsWith('00')) telefon = telefon.slice(2);
  if (/^05\d{9}$/.test(telefon)) telefon = '9' + telefon;
  if (/^5\d{9}$/.test(telefon)) telefon = '90' + telefon;

  const musteriAdi =
    String(j.profilAdi || '').trim() ||
    'WhatsApp Müşterisi';

  const mesaj =
    String(j.mesajMetni || '').trim() ||
    ('📎 ' + String(j.mesajTipi || 'Medya mesajı'));

  const now = $now.setZone('Europe/Istanbul');

  return {
    json: {
      marka: 'EFAS N TEPE',
      kaynak: 'META WHATSAPP',
      messageId: j.messageId || null,
      musteriAdi,
      telefon,
      telefonE164: telefon ? '+' + telefon : '',
      mesaj,
      mesajTipi: j.mesajTipi || null,
      tarih: now.toFormat('dd.MM.yyyy'),
      saat: now.toFormat('HH:mm:ss'),

      categoryId: 28,
      stageId: 'C28:UC_NHPUY5',
      stageAdi: 'META SMS GELEN',

      assignedById: atanan.id,
      assignedByName: atanan.ad
    }
  };
});
